{
  "title": "Research Best Practices for Supporting a Friend Through Burnout & Sleep Issues",
  "content": "This plan gathers evidence-based guidance across three distinct focus areas in parallel, then synthesizes everything into a comprehensive, actionable guide. Each research task digs into specific high-quality sources identified from prior searches to extract concrete advice.",
  "tasks": [
    {
      "goal": "Research how to be emotionally supportive of a burned-out friend without being preachy — gather specific communication techniques, what to say vs. not say, active listening strategies, and how to validate without fixing. Pull from: cliniclesalpes.com/blog/how-to-help-someone-with-burnout/, workplacestrategiesformentalhealth.com, headsupguys.org/help-friend-manage-stress/, teale.io/en/blog/how-to-support-someone-experiencing-burnout, and the Reddit socialwork thread.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research stress-relief activities specifically suited for doing together with a burned-out friend — categorize by energy level (low-energy for exhausted days vs. moderate-energy), indoor vs. outdoor, budget-friendly options, and activities that also help with sleep. Pull from: henryford.com/Blog/2020/06/Fun-Calming-Activities-Relieve-Stress, health.ucdavis.edu/blog/cultivating-health/feeling-burned-out-how-hobbies-laughter-and-enjoying-community-can-help/2024/02, positivepsychology.com/self-care-activities-groups/, notesbythalia.com/burnout-activities/, and thriveworks.com/blog/date-night-ideas-anxious-depressed-partner/.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research how to practically help a friend through a high-pressure deadline period without adding stress — including practical support (meals, errands, environment), how to check in without being intrusive, when to step back, and how to support sleep hygiene during crunch time. Pull from: friendshipwithintention.com/blog/60-ways-to-be-a-supportive-friend, studenthealth.virginia.edu/news/how-support-friend-who-struggling, mind.org.uk/information-support/types-of-mental-health-problems/stress/helping-someone-whos-stressed/, sleephealthfoundation.org.au/sleep-topics/burnout-and-sleep, and hopkinsmedicine.org/health/wellness-and-prevention/sleepless-nights-try-stress-relief-techniques.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Synthesize all findings from the three research threads into a comprehensive, well-organized guide with three main sections: (1) How to Be Supportive Without Being Preachy — communication dos/don'ts, phrases to use, validation techniques; (2) Stress-Relief Activities to Do Together — organized by energy level and setting, with specific suggestions; (3) Supporting Through a Deadline Period — practical help strategies, check-in approaches, sleep support tips. Include a quick-reference cheat sheet at the end with the top 10 most actionable tips across all three areas.",
      "tool_name": "reasoning",
      "depends_on": [0, 1, 2]
    }
